Here is the commit message:
spi: tegra: Fix a memory leak in tegra_slink_probe()

In tegra_slink_probe(), when platform_get_irq() fails, it directly
returns from the function with an error code, which causes a memory leak.

Replace it with a goto label to ensure proper cleanup.

Fixes: eb9913b511f1 ("spi: tegra: Fix missing IRQ check in tegra_slink_probe()")
Signed-off-by: Felix Gu <ustc.gu@gmail.com>
Reviewed-by: Jon Hunter <jonathanh@nvidia.com>
Link: https://patch.msgid.link/20260202-slink-v1-1-eac50433a6f9@gmail.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
In tegra_slink_probe(), when platform_get_irq() fails, the original code directly returns the error code without releasing previously acquired resources (such as clock enable, reset deassert, or PM runtime references), causing a memory/resource leak.

Here is the patch:

 static int tegra_slink_probe(struct platform_device *pdev)
 {
 	struct spi_controller	*host;
 	struct tegra_slink_data	*tspi;
 	struct resource		*r;
 	int ret, spi_irq;
 	const struct tegra_slink_chip_data *cdata = NULL;

 	cdata = of_device_get_match_data(&pdev->dev);

 	host = spi_alloc_host(&pdev->dev, sizeof(*tspi));
 	if (!host) {
 		dev_err(&pdev->dev, "host allocation failed\n");
 		return -ENOMEM;
 	}

 	/* the spi->mode bits understood by this driver: */
 	host->mode_bits = SPI_CPOL | SPI_CPHA | SPI_CS_HIGH;
 	host->setup = tegra_slink_setup;
 	host->prepare_message = tegra_slink_prepare_message;
 	host->transfer_one = tegra_slink_transfer_one;
 	host->unprepare_message = tegra_slink_unprepare_message;
 	host->auto_runtime_pm = true;
 	host->num_chipselect = MAX_CHIP_SELECT;

 	platform_set_drvdata(pdev, host);
 	tspi = spi_controller_get_devdata(host);
 	tspi->host = host;
 	tspi->dev = &pdev->dev;
 	tspi->chip_data = cdata;
 	spin_lock_init(&tspi->lock);

 	if (of_property_read_u32(tspi->dev->of_node, "spi-max-frequency",
 				 &host->max_speed_hz))
 		host->max_speed_hz = 25000000; /* 25MHz */

 	tspi->base = devm_platform_get_and_ioremap_resource(pdev, 0, &r);
 	if (IS_ERR(tspi->base)) {
 		ret = PTR_ERR(tspi->base);
 		goto exit_free_host;
 	}
 	tspi->phys = r->start;

 	/* disabled clock may cause interrupt storm upon request */
 	tspi->clk = devm_clk_get(&pdev->dev, NULL);
 	if (IS_ERR(tspi->clk)) {
 		ret = PTR_ERR(tspi->clk);
 		dev_err(&pdev->dev, "Can not get clock %d\n", ret);
 		goto exit_free_host;
 	}

 	tspi->rst = devm_reset_control_get_exclusive(&pdev->dev, "spi");
 	if (IS_ERR(tspi->rst)) {
 		dev_err(&pdev->dev, "can not get reset\n");
 		ret = PTR_ERR(tspi->rst);
 		goto exit_free_host;
 	}

 	ret = devm_tegra_core_dev_init_opp_table_common(&pdev->dev);
 	if (ret)
 		goto exit_free_host;

 	tspi->max_buf_size = SLINK_FIFO_DEPTH << 2;
 	tspi->dma_buf_size = DEFAULT_SPI_DMA_BUF_LEN;

 	ret = tegra_slink_init_dma_param(tspi, true);
 	if (ret < 0)
 		goto exit_free_host;
 	ret = tegra_slink_init_dma_param(tspi, false);
 	if (ret < 0)
 		goto exit_rx_dma_free;
 	tspi->max_buf_size = tspi->dma_buf_size;
 	init_completion(&tspi->tx_dma_complete);
 	init_completion(&tspi->rx_dma_complete);

 	init_completion(&tspi->xfer_completion);

 	pm_runtime_enable(&pdev->dev);
 	ret = pm_runtime_resume_and_get(&pdev->dev);
 	if (ret) {
 		dev_err(&pdev->dev, "pm runtime get failed, e = %d\n", ret);
 		goto exit_pm_disable;
 	}

 	reset_control_assert(tspi->rst);
 	udelay(2);
 	reset_control_deassert(tspi->rst);

 	spi_irq = platform_get_irq(pdev, 0);
-	if (spi_irq < 0)
-		return spi_irq;
+	if (spi_irq < 0) {
+		ret = spi_irq;
+		goto exit_pm_put;
+	}
 	tspi->irq = spi_irq;
 	ret = request_threaded_irq(tspi->irq, tegra_slink_isr,
 				   tegra_slink_isr_thread, IRQF_ONESHOT,
 				   dev_name(&pdev->dev), tspi);
 	if (ret < 0) {
 		dev_err(&pdev->dev, "Failed to register ISR for IRQ %d\n",
 			tspi->irq);
 		goto exit_pm_put;
 	}

 	tspi->def_command_reg  = SLINK_M_S;
 	tspi->def_command2_reg = SLINK_CS_ACTIVE_BETWEEN;
 	tegra_slink_writel(tspi, tspi->def_command_reg, SLINK_COMMAND);
 	tegra_slink_writel(tspi, tspi->def_command2_reg, SLINK_COMMAND2);

 	host->dev.of_node = pdev->dev.of_node;
 	ret = spi_register_controller(host);
 	if (ret < 0) {
 		dev_err(&pdev->dev, "can not register to host err %d\n", ret);
 		goto exit_free_irq;
 	}

 	pm_runtime_put(&pdev->dev);

 	return ret;

 exit_free_irq:
 	free_irq(spi_irq, tspi);
 exit_pm_put:
 	pm_runtime_put(&pdev->dev);
 exit_pm_disable:
 	pm_runtime_force_suspend(&pdev->dev);

 	tegra_slink_deinit_dma_param(tspi, false);
 exit_rx_dma_free:
 	tegra_slink_deinit_dma_param(tspi, true);
 exit_free_host:
 	spi_controller_put(host);
 	return ret;
 }



